insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$bastos$q$, $q$https://www.dosp.com.br/exibe_do.php?i=NTEwMDA1 (Diário Oficial de Bastos nº 523, 19/06/2024, p. 4-5: Decreto 1.758/2024)$q$, $q$Ato oficial de Bastos: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0); vicinais: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), cortadas no limite municipal do IBGE.$q$, 89, $q$Dec. 1.758/2024, art. 1º: caminhões com 7 eixos ou mais (carreta + cavalo, bitrem, treminhão, tritrem, rodotrem), carregados ou não, proibidos no perímetro urbano e nas vicinais BAS 010, BAS 020 e BAS 050/168/152, 24 h, ressalvada carga/descarga com nota fiscal. O perímetro urbano não é delimitado no decreto (zona aproximada pelos setores urbanos do IBGE). Canavieiros, esterco e aves mortas (art. 1º, §2º, e art. 3º) dependem do tipo de carga: desativada.$q$);
